});
return [{ json: { query: clean } }];

const q = $input.first().json.query;
let where = "l.status != 'cancelado'";
if (q.tipo) where += " AND l.tipo = '" + q.tipo + "'";
if (q.status) where += " AND l.status = '" + q.status + "'";
if (q.categoria_id) where += " AND l.categoria_id::text = '" + q.categoria_id + "'";
if (q.de) where += " AND l.vencimento >= '" + q.de + "'::date";
if (q.ate) where += " AND l.vencimento <= '" + q.ate + "'::date";
const inner = "SELECT l.*, c.nome as categoria_nome FROM financeiro.lancamentos l LEFT JOIN financeiro.categorias c ON l.categoria_id = c.id WHERE " + where + " ORDER BY l.created_at DESC LIMIT 100";
const sql = "SELECT COALESCE(json_agg(sub), '[]'::json) as data FROM (" + inner + ") sub;";
return [{ json: { sql } }];

const result = $input.first().json;
const items = result.data || [];
return [{ json: { __body: JSON.stringify(items) } }];

