const q = $input.first().json.query;
let where = "status != 'cancelado'";
if (q.de) where += " AND vencimento >= '" + q.de + "'::date";
if (q.ate) where += " AND vencimento <= '" + q.ate + "'::date";
const sql = "SELECT COALESCE(SUM(CASE WHEN tipo IN ('a_pagar','pago') THEN valor END), 0) as total_despesas, COALESCE(SUM(CASE WHEN tipo IN ('a_receber','recebido') THEN valor END), 0) as total_receitas, COALESCE(SUM(CASE WHEN tipo = 'a_pagar' AND status = 'pendente' THEN valor END), 0) as a_pagar_pendente, COALESCE(SUM(CASE WHEN tipo = 'a_receber' AND status = 'pendente' THEN valor END), 0) as a_receber_pendente, COALESCE(SUM(CASE WHEN tipo IN ('a_receber','recebido') THEN valor END), 0) - COALESCE(SUM(CASE WHEN tipo IN ('a_pagar','pago') THEN valor END), 0) as saldo_previsto FROM financeiro.lancamentos WHERE " + where + ";";
return [{ json: { sql } }];

