const inner = "SELECT l.tipo, l.descricao, l.valor, l.vencimento, l.pagamento_data, c.nome as categoria, l.fornecedor, l.cliente, l.numero_doc, l.status, l.created_at FROM financeiro.lancamentos l LEFT JOIN financeiro.categorias c ON l.categoria_id = c.id WHERE " + where + " ORDER BY l.vencimento DESC";
