const result = $input.first().json;
const items = result.data || [];
if (items.length === 0) return [{ json: { csv: 'Sem dados para exportar' } }];
const headers = Object.keys(items[0]);
const csv = [headers.join(';')].concat(
  items.map(row => headers.map(h => {
    let v = row[h] == null ? '' : String(row[h]);
    if (v.includes(';') || v.includes('"')) v = '"' + v.replace(/"/g, '""') + '"';
    return v;
  }).join(';'))
).join('\n');
return [{ json: { csv } }];

const b = $input.first().json.body || {};
const clean = {};
const keys = ['action','id','tipo','descricao','valor','vencimento','categoria_id','fornecedor','cliente','numero_doc','observacoes','status'];
keys.forEach(k => {
  const v = b[k];
  clean[k] = (v !== undefined && v !== null && String(v) !== 'undefined' && String(v) !== 'null') ? v : '';
});
return [{ json: { body: clean } }];

const b = $input.first().json.body;
const venc = b.vencimento ? "'" + b.vencimento + "'" : 'NULL';
const cat = b.categoria_id ? b.categoria_id : 'NULL';
const sql = "INSERT INTO financeiro.lancamentos (tipo, descricao, valor, vencimento, categoria_id, fornecedor, cliente, numero_doc, observacoes, source, created_by) VALUES ('" + b.tipo + "', '" + (b.descricao || '') + "', " + b.valor + ", " + venc + ", " + cat + ", '" + (b.fornecedor || '') + "', '" + (b.cliente || '') + "', '" + (b.numero_doc || '') + "', '" + (b.observacoes || '') + "', 'dashboard', 'dashboard') RETURNING *;";
return [{ json: { sql } }];

const b = $input.first().json.body;
let sets = [];
if (b.tipo) sets.push("tipo = '" + b.tipo + "'");
if (b.descricao) sets.push("descricao = '" + b.descricao + "'");
if (b.valor) sets.push('valor = ' + b.valor);
if (b.vencimento) sets.push("vencimento = '" + b.vencimento + "'");
if (b.categoria_id) sets.push('categoria_id = ' + b.categoria_id);
if (b.status) sets.push("status = '" + b.status + "'");
sets.push('updated_at = now()');
const sql = 'UPDATE financeiro.lancamentos SET ' + sets.join(', ') + " WHERE id = '" + b.id + "'::uuid RETURNING *;";
return [{ json: { sql } }];

const input = $input.first().json;
const id = input.body?.id || input.id;
if (!id || typeof id !== 'string' || id.length === 0) {
  return [{ json: { error: 'ID inválido', sql: null } }];
}
const sql = `DELETE FROM financeiro.lancamentos WHERE id = '${id}'::uuid RETURNING id;`;
return [{ json: { sql } }];

